.brotato-arena-bar{position:relative;overflow:hidden;border:1px solid #0006;box-shadow:0 2px 8px #0006}
.brotato-arena-bar i{position:absolute;inset:0 auto 0 0;width:0;height:100%;transition:width .16s}
.brotato-arena-bar span{position:relative;z-index:2;display:block;padding:0 8px;color:#fff;font:800 12px/1 ui-sans-serif,system-ui,sans-serif;text-shadow:0 1px 2px #000a}
.brotato-arena-hp{height:22px;background:#3a1515;border-radius:3px}
.brotato-arena-hp [data-slot=health]{z-index:1;background:#c43b3b}
.brotato-arena-hp .residual{z-index:0;background:#fff;opacity:0}
.brotato-arena-hp .residual.active{opacity:.7}
.brotato-arena-hp span{line-height:22px;text-align:center}
.brotato-arena-xp{height:14px;background:#16301a;border-radius:2px}
.brotato-arena-xp [data-slot=xp-progress]{background:#3d9e4a}
.brotato-arena-xp span{line-height:14px;text-align:right;font-size:11px}
.brotato-m8-ui.low-health .brotato-arena-hp{border-color:#ff6b6b;animation:brotato-pulse .72s ease-in-out infinite}
.brotato-arena-currencies{display:grid;gap:4px;margin-top:3px;color:#fff;font:800 16px/1 ui-sans-serif,system-ui,sans-serif;text-shadow:0 1px 3px #000a}
.brotato-arena-currency{display:flex;align-items:center;gap:8px}
.brotato-test-grant-materials{pointer-events:auto;margin-left:2px;padding:2px 6px;color:#101820;background:#ffd166;border:0;border-radius:3px;font:800 10px inherit;cursor:pointer}
.brotato-arena-coin,.brotato-arena-sack{flex:0 0 auto}
.brotato-arena-coin{width:16px;height:16px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#d6ff8a,#4bb24a 62%,#2d7a32);box-shadow:inset 0 0 0 2px #1d4f22,0 1px 2px #0008}
.brotato-arena-sack{width:15px;height:17px;border-radius:4px 4px 3px 3px;background:linear-gradient(#c9a36a,#8a6232);box-shadow:inset 0 1px 0 #e6c48a,0 1px 2px #0008}
.brotato-arena-hud-center{display:grid;justify-items:center;padding-top:2px;color:#fff;text-shadow:0 2px 8px #000c}
.brotato-arena-hud-center b{font-size:16px;letter-spacing:.04em}
.brotato-arena-hud-center strong{font-size:36px;line-height:1;letter-spacing:.02em}
.brotato-arena-hud-right{display:grid;justify-items:end;gap:8px}
.brotato-arena-hud .brotato-hud-pause{width:26px;height:26px;margin:0;pointer-events:auto}
.brotato-arena-badges{display:grid;gap:8px;justify-items:end}
.brotato-arena-badge{display:grid;grid-template-columns:28px auto;align-items:center;gap:6px;color:#fff;text-shadow:0 1px 3px #000a}
.brotato-arena-badge.empty{opacity:.42}
.brotato-arena-badge b{font-size:16px}
.brotato-arena-upgrade-icon,.brotato-arena-crate-icon{display:block;width:26px;height:26px;position:relative}
.brotato-arena-upgrade-icon{width:24px;height:23px;margin-top:3px;border-radius:45% 45% 48% 48%;background:radial-gradient(circle at 32% 28%,#ffad8e,#ef4439 40%,#b71f28 83%);box-shadow:inset -2px -2px 0 #861921,0 1px 3px #0008}
.brotato-arena-upgrade-icon:before{content:'';position:absolute;left:5px;top:-5px;width:16px;height:11px;background:#389a40;clip-path:polygon(45% 0,59% 34%,100% 19%,73% 57%,88% 94%,50% 73%,13% 100%,24% 58%,0 25%,39% 34%)}
.brotato-arena-upgrade-icon:after{content:'';position:absolute;right:-7px;top:-5px;width:12px;height:20px;background:#a6ff8c;clip-path:polygon(50% 0,100% 40%,72% 40%,72% 100%,28% 100%,28% 40%,0 40%);filter:drop-shadow(0 1px 1px #173820)}
.brotato-arena-badge:not(.empty) .brotato-arena-upgrade-icon:after{animation:brotato-upgrade-rise 1.1s ease-in-out infinite}
.brotato-arena-badge:not(.empty) .brotato-arena-upgrade-icon{filter:drop-shadow(0 0 3px #ffdb7080)}
@keyframes brotato-upgrade-rise{50%{transform:translateY(-4px);background:#fff3a2}}
.brotato-arena-sack.receiving{animation:brotato-bag-receive .18s ease-in-out infinite}
@keyframes brotato-bag-receive{50%{transform:scale(1.24);filter:drop-shadow(0 0 5px #a6ff8c)}}
@media(prefers-reduced-motion:reduce){.brotato-arena-badge:not(.empty) .brotato-arena-upgrade-icon:after,.brotato-arena-sack.receiving{animation:none}}
.brotato-arena-crate-icon{border-radius:3px;background:linear-gradient(#c48a4a,#8a5a28);box-shadow:inset 0 0 0 2px #5a3514,0 1px 3px #0008}
.brotato-arena-crate-icon:before,.brotato-arena-crate-icon:after{content:'';position:absolute;background:#5a3514}
.brotato-arena-crate-icon:before{left:0;right:0;top:11px;height:2px}
.brotato-arena-crate-icon:after{top:0;bottom:0;left:12px;width:2px}
.brotato-arena-hud .brotato-test-debug-button{position:static;margin-top:2px;pointer-events:auto}
.brotato-test-hud-toggles{display:grid;gap:4px;justify-items:end;pointer-events:auto;color:#fff;font:700 10px/1.2 ui-sans-serif,system-ui,sans-serif;text-shadow:0 1px 2px #000a}
.brotato-test-hud-toggles[hidden]{display:none}
.brotato-test-hud-toggles label{display:flex;align-items:center;gap:4px;padding:3px 6px;background:#101820cc;border:1px solid #8ee7bd55;border-radius:3px;cursor:pointer;white-space:nowrap}
.brotato-test-hud-toggles input{accent-color:#8ee7bd}
.brotato-itemfound{position:absolute;inset:0;z-index:41;display:block;padding:0;background:#05090d99;border:0;border-radius:0;box-shadow:none;pointer-events:auto;overflow:hidden}
.brotato-itemfound-stage{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:24px;align-items:center;min-height:100%;padding:88px 28px 28px}
.brotato-itemfound-modal{justify-self:center;width:min(420px,100%);text-align:center}
.brotato-itemfound-modal h2{margin:0;color:#fff;font-size:clamp(34px,5vw,48px);letter-spacing:.02em;text-shadow:0 4px 16px #000a}
.brotato-itemfound-remaining{min-height:18px;margin:8px 0 0;color:#8ee7bd;font-size:13px}
.brotato-itemfound-card{margin-top:18px;padding:16px;text-align:left;background:#141c22f2;border:2px solid var(--tier,#496474);border-radius:8px;box-shadow:0 12px 28px #0006}
.brotato-itemfound-card-top{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:8px}
.brotato-itemfound-card-top strong{display:block;font-size:18px}
.brotato-itemfound-card-top small{display:block;margin-top:3px;color:#b9c8d2;font-size:12px}
.brotato-itemfound-card .brotato-card-attributes{grid-template-columns:1fr}
.brotato-itemfound-actions{display:grid;gap:10px;margin-top:16px}
.brotato-itemfound-actions .brotato-button{width:100%;min-height:42px;font-size:16px}
.brotato-itemfound-take{color:#101820;background:#c8cdd2}
.brotato-itemfound-recycle{display:flex;align-items:center;justify-content:center;gap:10px;color:#f5f7fb;background:#14181c}
.brotato-itemfound-recycle .brotato-keycap{background:#2a3138}
.brotato-itemfound-stats{min-height:min(620px,calc(100vh - 130px))}
@media(max-width:760px){.brotato-arena-hud{grid-template-columns:minmax(180px,1fr) auto auto}.brotato-arena-hud-center strong{font-size:28px}.brotato-itemfound-stage{grid-template-columns:1fr;padding:78px 16px 16px}.brotato-itemfound-stats{min-height:0;order:2}.brotato-itemfound-stats .brotato-stat-list{grid-template-columns:repeat(2,minmax(0,1fr))}}
